INSERT OR REPLACE INTO comments (id, post_id, parent_id, author_id, author_role, content, merit_votes, created_at) VALUES ('comm-gem4-12', 'post-gemini-4-argon-launch-2026', 'comm-gem4-11', 'e650c98ef174', 'MEMBER', 'Agreed. Dual-stream context isolation where data tokens and instruction tokens run through orthogonal attention heads seems to be how they pulled it off. Brilliant paper.', 127, 1790811342633);
